-- TEXT timestamps/JSON retain the existing API wire format and local-calendar semantics.
-- Binary collation and ASCII-only case folding match SQLite NOCASE exactly.
CREATE FUNCTION focus_ascii_fold(value text) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
 SELECT translate(value,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz') COLLATE "C"
$$;
CREATE TABLE IF NOT EXISTS users (
 id TEXT COLLATE "C" PRIMARY KEY, email TEXT COLLATE "C" NOT NULL, password_hash TEXT COLLATE "C" NOT NULL, display_name TEXT COLLATE "C" NOT NULL,
 timezone TEXT COLLATE "C" NOT NULL DEFAULT 'Europe/Madrid', theme TEXT COLLATE "C" NOT NULL DEFAULT 'system' CHECK(theme IN ('light','dark','system')),
 preferred_task_view TEXT COLLATE "C" NOT NULL DEFAULT 'board' CHECK(preferred_task_view IN ('board','table')), week_start_day INTEGER NOT NULL DEFAULT 1 CHECK(week_start_day IN (0,1)), created_at TEXT COLLATE "C" NOT NULL
);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT COLLATE "C" PRIMARY KEY, name TEXT COLLATE "C" NOT NULL, owner_user_id TEXT COLLATE "C" NOT NULL UNIQUE REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE, created_at TEXT COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE, user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE, role TEXT COLLATE "C" NOT NULL CHECK(role IN ('owner','admin','member')), created_at TEXT COLLATE "C" NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT COLLATE "C" PRIMARY KEY, user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE, csrf_token TEXT COLLATE "C" NOT NULL, expires_at TEXT COLLATE "C" NOT NULL, created_at TEXT COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS strategic_goals (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,title TEXT COLLATE "C" NOT NULL,description TEXT COLLATE "C" NOT NULL DEFAULT '',period_start TEXT COLLATE "C",period_end TEXT COLLATE "C",status TEXT COLLATE "C" NOT NULL DEFAULT 'active' CHECK(status IN ('active','achieved','paused','archived')),sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS projects (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,name TEXT COLLATE "C" NOT NULL,slug TEXT COLLATE "C" NOT NULL,description TEXT COLLATE "C" NOT NULL DEFAULT '',goal_id TEXT COLLATE "C",color TEXT COLLATE "C" NOT NULL DEFAULT '#39786b',icon TEXT COLLATE "C" NOT NULL DEFAULT 'folder',status TEXT COLLATE "C" NOT NULL DEFAULT 'active' CHECK(status IN ('active','on_hold','archived')),target_date TEXT COLLATE "C",sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,UNIQUE(workspace_id,slug),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,goal_id) REFERENCES strategic_goals(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS milestones (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,title TEXT COLLATE "C" NOT NULL,description TEXT COLLATE "C" NOT NULL DEFAULT '',project_id TEXT COLLATE "C",goal_id TEXT COLLATE "C",status TEXT COLLATE "C" NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','achieved')),achieved_at TEXT COLLATE "C",sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE,FOREIGN KEY(workspace_id,goal_id) REFERENCES strategic_goals(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS tasks (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,title TEXT COLLATE "C" NOT NULL,description TEXT COLLATE "C" NOT NULL DEFAULT '',project_id TEXT COLLATE "C",parent_task_id TEXT COLLATE "C",status TEXT COLLATE "C" NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','pending_review','waiting_external','blocked','completed','cancelled')),priority TEXT COLLATE "C" NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','critical')),due_at TEXT COLLATE "C",waiting_on TEXT COLLATE "C" NOT NULL DEFAULT '',follow_up_at TEXT COLLATE "C",completed_at TEXT COLLATE "C",cancelled_at TEXT COLLATE "C",deleted_at TEXT COLLATE "C",created_by_user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,tags TEXT COLLATE "C" NOT NULL DEFAULT '[]',created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE,FOREIGN KEY(workspace_id,parent_task_id) REFERENCES tasks(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS task_events (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL,task_id TEXT COLLATE "C" NOT NULL,actor_user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,event_type TEXT COLLATE "C" NOT NULL,from_value_json TEXT COLLATE "C",to_value_json TEXT COLLATE "C",occurred_at TEXT COLLATE "C" NOT NULL,FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS journal_entries (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,author_user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,entry_date TEXT COLLATE "C" NOT NULL,title TEXT COLLATE "C" NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,UNIQUE(workspace_id,author_user_id,entry_date),UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS journal_blocks (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL,journal_entry_id TEXT COLLATE "C" NOT NULL,block_type TEXT COLLATE "C" NOT NULL CHECK(block_type IN ('heading','paragraph','bullet','task_reference')),text_content TEXT COLLATE "C" NOT NULL DEFAULT '',task_id TEXT COLLATE "C",indent_level INTEGER NOT NULL DEFAULT 0 CHECK(indent_level BETWEEN 0 AND 8),sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,updated_at TEXT COLLATE "C" NOT NULL,FOREIGN KEY(workspace_id,journal_entry_id) REFERENCES journal_entries(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE,FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS focus_items (storage_order BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT COLLATE "C" PRIMARY KEY,workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,user_id TEXT COLLATE "C" NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,task_id TEXT COLLATE "C" NOT NULL,period_type TEXT COLLATE "C" NOT NULL CHECK(period_type IN ('daily','weekly')),period_start TEXT COLLATE "C" NOT NULL,sort_order DOUBLE PRECISION NOT NULL DEFAULT 0,created_at TEXT COLLATE "C" NOT NULL,UNIQUE(user_id,task_id,period_type,period_start),FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS idempotency_keys (workspace_id TEXT COLLATE "C" NOT NULL REFERENCES workspaces(id) DEFERRABLE INITIALLY IMMEDIATE,request_id TEXT COLLATE "C" NOT NULL,result_json TEXT COLLATE "C" NOT NULL,created_at TEXT COLLATE "C" NOT NULL,PRIMARY KEY(workspace_id,request_id));
CREATE INDEX IF NOT EXISTS task_state ON tasks(workspace_id,status,priority);
CREATE INDEX IF NOT EXISTS events_period ON task_events(workspace_id,occurred_at);
CREATE INDEX IF NOT EXISTS events_task ON task_events(task_id,occurred_at);
CREATE INDEX IF NOT EXISTS journal_date ON journal_entries(author_user_id,entry_date);
CREATE INDEX IF NOT EXISTS focus_period ON focus_items(user_id,period_type,period_start);

CREATE UNIQUE INDEX users_email_fold ON users(focus_ascii_fold(email));
